Write `initials(fullName)`: `"Ada Lovelace"` → `"A.L."`. Names may be lower-case and have extra spaces.

```js
function initials(fullName) {
  // TODO
  return "";
}
```

notes.back:
// Why: `split(" ")` leaves empty strings between repeated spaces; trim first and split on
// the pattern /\s+/ (one or more whitespace characters).
// Docs: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String/split
function initials(fullName) {
  return fullName
    .trim()
    .split(/\s+/)
    .map((part) => part[0].toUpperCase() + ".")
    .join("");
}

